import { useState, useEffect, useCallback, useRef } from 'react';
import { resolveAssetUrl } from '@/utils/basename';
import { logger, scopedStorage } from '@lark-apaas/client-toolkit-lite';

const DB_NAME = 'app_ledlight_db';
const STORE_NAME = 'video_files';
const DB_VERSION = 2; // 升级版本以支持多视频
const STORAGE_KEY = '__app_ledlight_factory_video_settings';
const STORAGE_VERSION = 1;

// 默认视频路径（静态文件，用户没上传时用占位）
const DEFAULT_VIDEO_HOME = '';
const DEFAULT_VIDEO_ABOUT = '';

export interface IFactoryVideoSettings {
  enabled: boolean;          // 总开关
  showOnHome: boolean;       // 首页展示开关
  showOnAbout: boolean;      // About 页面展示开关
  homeVideoName: string;     // 首页视频文件名
  aboutVideoName: string;    // About 视频文件名
  homeVideoUrl: string;      // 首页视频 URL（远程/默认）
  aboutVideoUrl: string;     // About 视频 URL（远程/默认）
  posterUrl: string;         // 封面图 URL（可选）
  videoTitle: string;        // 视频标题
  autoPlay: boolean;         // 自动播放（静音循环）
  showControls: boolean;     // 显示控制条
  updatedAt: number;
}

interface IVideoRecord {
  id: string;           // 'home' 或 'about'
  file: Blob;
  name: string;
  size: number;
  uploadDate: number;
}

export interface IVideoInfo {
  url: string;
  name: string;
  size: number;
  isCustom: boolean;
  uploadDate?: number;
}

export interface IFactoryVideoState {
  settings: IFactoryVideoSettings;
  homeVideo: IVideoInfo;
  aboutVideo: IVideoInfo;
}

const DEFAULT_SETTINGS: IFactoryVideoSettings = {
  enabled: false,
  showOnHome: true,
  showOnAbout: true,
  homeVideoName: '',
  aboutVideoName: '',
  homeVideoUrl: DEFAULT_VIDEO_HOME,
  aboutVideoUrl: DEFAULT_VIDEO_ABOUT,
  posterUrl: '',
  videoTitle: 'Factory Tour',
  autoPlay: true,
  showControls: true,
  updatedAt: 0,
};

function getDefaultVideoUrl(): string {
  // 目前没有默认视频，返回空字符串
  return '';
}

/* ===== IndexedDB ===== */

function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);
    request.onupgradeneeded = (e) => {
      const db = (e.target as IDBOpenDBRequest).result;
      // 视频文件 store
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
  });
}

async function getVideoRecord(db: IDBDatabase, id: string): Promise<IVideoRecord | null> {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.get(id);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result || null);
  });
}

async function saveVideoRecord(db: IDBDatabase, record: IVideoRecord): Promise<void> {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.put(record);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function deleteVideoRecord(db: IDBDatabase, id: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

/* ===== Settings 存储 ===== */

function loadSettings(): IFactoryVideoSettings {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULT_SETTINGS };
    const parsed = JSON.parse(raw);
    if (parsed.__version === STORAGE_VERSION && parsed.data) {
      return { ...DEFAULT_SETTINGS, ...parsed.data };
    }
  } catch (e) {
    logger.warn('[FactoryVideo] Failed to load settings:', String(e));
  }
  return { ...DEFAULT_SETTINGS };
}

function saveSettings(settings: IFactoryVideoSettings): void {
  try {
    scopedStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({ __version: STORAGE_VERSION, data: settings })
    );
  } catch (e) {
    logger.warn('[FactoryVideo] Failed to save settings:', String(e));
  }
}

/* ===== Hook ===== */

export function useFactoryVideo() {
  const [settings, setSettingsState] = useState<IFactoryVideoSettings>(() => loadSettings());
  const [homeVideo, setHomeVideo] = useState<IVideoInfo>({
    url: getDefaultVideoUrl(),
    name: '',
    size: 0,
    isCustom: false,
  });
  const [aboutVideo, setAboutVideo] = useState<IVideoInfo>({
    url: getDefaultVideoUrl(),
    name: '',
    size: 0,
    isCustom: false,
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const homeUrlRef = useRef<string | null>(null);
  const aboutUrlRef = useRef<string | null>(null);

  const revokeUrl = useCallback((ref: React.MutableRefObject<string | null>) => {
    if (ref.current) {
      URL.revokeObjectURL(ref.current);
      ref.current = null;
    }
  }, []);

  // 初始化：从 IndexedDB 读取视频
  useEffect(() => {
    let cancelled = false;
    async function load() {
      try {
        const db = await openDB();
        const [homeRec, aboutRec] = await Promise.all([
          getVideoRecord(db, 'home'),
          getVideoRecord(db, 'about'),
        ]);
        db.close();

        if (!cancelled && homeRec && homeRec.file) {
          revokeUrl(homeUrlRef);
          const url = URL.createObjectURL(homeRec.file);
          homeUrlRef.current = url;
          setHomeVideo({
            url,
            name: homeRec.name,
            size: homeRec.size,
            isCustom: true,
            uploadDate: homeRec.uploadDate,
          });
        }
        if (!cancelled && aboutRec && aboutRec.file) {
          revokeUrl(aboutUrlRef);
          const url = URL.createObjectURL(aboutRec.file);
          aboutUrlRef.current = url;
          setAboutVideo({
            url,
            name: aboutRec.name,
            size: aboutRec.size,
            isCustom: true,
            uploadDate: aboutRec.uploadDate,
          });
        }
      } catch (e) {
        logger.warn('[FactoryVideo] Failed to load from IndexedDB:', String(e));
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    load();
    return () => {
      cancelled = true;
    };
  }, [revokeUrl]);

  // 卸载释放 URL
  useEffect(() => {
    return () => {
      revokeUrl(homeUrlRef);
      revokeUrl(aboutUrlRef);
    };
  }, [revokeUrl]);

  // 应用远程 URL 覆盖（当远程 data/factory-video.json 有值时）
  const applyRemoteUrls = useCallback((remoteHomeUrl: string, remoteAboutUrl: string, remotePosterUrl?: string) => {
    // 如果本地上传了自定义视频，优先用本地（等同步到 GitHub 后两端一致）
    // 只有本地没有自定义时才用远程 URL
    if (!homeVideo.isCustom && remoteHomeUrl) {
      const fullUrl = remoteHomeUrl.startsWith('http') || remoteHomeUrl.startsWith('data:')
        ? remoteHomeUrl
        : resolveAssetUrl(remoteHomeUrl);
      setHomeVideo((prev) => ({ ...prev, url: fullUrl, name: prev.name || 'factory-video-home.mp4' }));
    }
    if (!aboutVideo.isCustom && remoteAboutUrl) {
      const fullUrl = remoteAboutUrl.startsWith('http') || remoteAboutUrl.startsWith('data:')
        ? remoteAboutUrl
        : resolveAssetUrl(remoteAboutUrl);
      setAboutVideo((prev) => ({ ...prev, url: fullUrl, name: prev.name || 'factory-video-about.mp4' }));
    }
    if (remotePosterUrl) {
      setSettingsState((prev) => ({ ...prev, posterUrl: remotePosterUrl }));
    }
  }, [homeVideo.isCustom, aboutVideo.isCustom]);

  // 更新设置
  const updateSettings = useCallback((updates: Partial<IFactoryVideoSettings>) => {
    setSettingsState((prev) => {
      const next = { ...prev, ...updates, updatedAt: Date.now() };
      saveSettings(next);
      return next;
    });
  }, []);

  // 上传视频
  const uploadVideo = useCallback(async (target: 'home' | 'about', file: File): Promise<boolean> => {
    // 视频类型校验
    if (!file.type.startsWith('video/') &&
        !/\.(mp4|webm|ogg|mov)$/i.test(file.name)) {
      return false;
    }
    // 大小限制 100MB
    if (file.size > 100 * 1024 * 1024) {
      return false;
    }

    setSaving(true);
    try {
      const db = await openDB();
      const record: IVideoRecord = {
        id: target,
        file,
        name: file.name,
        size: file.size,
        uploadDate: Date.now(),
      };
      await saveVideoRecord(db, record);
      db.close();

      const urlRef = target === 'home' ? homeUrlRef : aboutUrlRef;
      const setVideo = target === 'home' ? setHomeVideo : setAboutVideo;
      const nameKey = target === 'home' ? 'homeVideoName' : 'aboutVideoName';

      revokeUrl(urlRef);
      const url = URL.createObjectURL(file);
      urlRef.current = url;
      setVideo({
        url,
        name: file.name,
        size: file.size,
        isCustom: true,
        uploadDate: record.uploadDate,
      });
      updateSettings({ [nameKey]: file.name } as Partial<IFactoryVideoSettings>);
      return true;
    } catch (e) {
      logger.warn(`[FactoryVideo] Upload ${target} failed:`, String(e));
      return false;
    } finally {
      setSaving(false);
    }
  }, [revokeUrl, updateSettings]);

  // 重置视频（删除自定义）
  const resetVideo = useCallback(async (target: 'home' | 'about'): Promise<boolean> => {
    try {
      const db = await openDB();
      await deleteVideoRecord(db, target);
      db.close();

      const urlRef = target === 'home' ? homeUrlRef : aboutUrlRef;
      const setVideo = target === 'home' ? setHomeVideo : setAboutVideo;
      const nameKey = target === 'home' ? 'homeVideoName' : 'aboutVideoName';

      revokeUrl(urlRef);
      setVideo({
        url: getDefaultVideoUrl(),
        name: '',
        size: 0,
        isCustom: false,
      });
      updateSettings({ [nameKey]: '' } as Partial<IFactoryVideoSettings>);
      return true;
    } catch (e) {
      logger.warn(`[FactoryVideo] Reset ${target} failed:`, String(e));
      return false;
    }
  }, [revokeUrl, updateSettings]);

  // 用于同步：获取视频原始 Blob（写入 GitHub 用）
  const getVideoBlob = useCallback(async (target: 'home' | 'about'): Promise<Blob | null> => {
    try {
      const db = await openDB();
      const rec = await getVideoRecord(db, target);
      db.close();
      return rec?.file ?? null;
    } catch {
      return null;
    }
  }, []);

  return {
    settings,
    homeVideo,
    aboutVideo,
    loading,
    saving,
    updateSettings,
    uploadVideo,
    resetVideo,
    getVideoBlob,
    applyRemoteUrls,
  };
}

/* ===== 独立导出：供同步模块调用（不依赖 Hook） ===== */

/**
 * 从 IndexedDB 读取指定视频的 Blob（非 Hook 版本，供同步模块调用）
 */
export async function getFactoryVideoBlob(target: 'home' | 'about'): Promise<Blob | null> {
  try {
    const db = await openDB();
    const rec = await getVideoRecord(db, target);
    db.close();
    return rec?.file ?? null;
  } catch (e) {
    logger.warn('[FactoryVideo] getFactoryVideoBlob failed:', String(e));
    return null;
  }
}

/**
 * 读取工厂视频设置（非 Hook 版本，供同步模块调用）
 */
export function readFactoryVideoSettings(): IFactoryVideoSettings {
  return loadSettings();
}

/**
 * ArrayBuffer 转 Base64 字符串（供同步上传使用）
 */
export function arrayBufferToBase64(buffer: ArrayBuffer): string {
  let binary = '';
  const bytes = new Uint8Array(buffer);
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    const chunk = bytes.subarray(i, i + chunkSize);
    binary += String.fromCharCode.apply(null, chunk as unknown as number[]);
  }
  return btoa(binary);
}
